/** The bars of a skeleton, named as the CSS modifiers: title 20 dp × 40 %, long 12 dp × 90 %, short 12 dp × 55 %. */
enum class SbSkeletonLine { Title, Long, Short }

/**
 * Skeleton for remote content over 1 s (spec/02 §3.12): [label] („Wird geladen …“, table) above static bars in
 * border grey; no shimmer and no movement (D80). Remove it when the content arrives.
 */
@Composable
fun SbSkeleton(
    modifier: Modifier = Modifier,
    lines: List<SbSkeletonLine> = listOf(SbSkeletonLine.Title, SbSkeletonLine.Long, SbSkeletonLine.Short),
    label: String = sbMessages().loading,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    Column(
        modifier
            .fillMaxWidth()
            .semantics(mergeDescendants = true) { liveRegion = LiveRegionMode.Polite },
        verticalArrangement = Arrangement.spacedBy(t.space.s2),
    ) {
        Text(label, style = SebaroTheme.typography.caption, color = c.textMuted)
        lines.forEach { line ->
            val (height, share) = when (line) {
                SbSkeletonLine.Title -> t.space.s5 to 0.4f
                SbSkeletonLine.Long -> t.space.s3 to 0.9f
                SbSkeletonLine.Short -> t.space.s3 to 0.55f
            }
            Box(Modifier.fillMaxWidth(share).height(height).background(c.border, t.shapes.small))
        }
